const byText = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0)

const mapSequential = <T, R>(
  items: readonly T[],
  fn: (item: T) => Promise<R>,
): Promise<readonly R[]> =>
  items.reduce<Promise<readonly R[]>>(
    async (acc, item) => [...(await acc), await fn(item)],
    Promise.resolve([]),
  )

const toPosix = (path: string): string => path.split(sep).join('/')

const keyOf = (file: SessionFile): string => `${file.project}/${file.path}`

const isInside = (parent: string, child: string): boolean => {
  const rel = relative(parent, child)
  return (
    rel === '' ||
    (rel !== '..' && !rel.startsWith(`..${sep}`) && !isAbsolute(rel))
  )
}

const assertDisjoint = (sourceRoot: string, dest: string): void => {
  const source = resolve(sourceRoot)
  const target = resolve(dest)
  if (isInside(source, target) || isInside(target, source)) {
    throw new Error(`Source and destination overlap: ${source} and ${target}`)
  }
}

const readDirents = (dir: string, label: string) =>
  readdir(dir, { withFileTypes: true }).catch((error: unknown) => {
    throw new Error(`${label} folder not readable: ${dir}`, { cause: error })
  })

const listFilesUnder = async (
  dir: string,
  label: string,
): Promise<readonly string[]> =>
  (
    await readdir(dir, { recursive: true, withFileTypes: true }).catch(
      (error: unknown) => {
        throw new Error(`${label} folder not readable: ${dir}`, {
          cause: error,
        })
      },
    )
  )
    .filter((entry) => entry.isFile())
    .map((entry) => toPosix(relative(dir, join(entry.parentPath, entry.name))))
    .sort(byText)

const listProjectFiles = async (
  sourceRoot: string,
  project: string,
): Promise<readonly SessionFile[]> => {
  const projectDir = join(sourceRoot, project)
  const entries = await readDirents(projectDir, 'Source')
  const sessions = entries.filter(
    (entry) =>
      entry.isFile() &&
      entry.name.endsWith(SESSION_EXTENSION) &&
      entry.name.length > SESSION_EXTENSION.length,
  )
  const nested = await mapSequential(sessions, async (session) => {
    const stem = session.name.slice(0, -SESSION_EXTENSION.length)
    const hasSibling = entries.some(
      (entry) => entry.isDirectory() && entry.name === stem,
    )
    const inside = hasSibling
      ? (await listFilesUnder(join(projectDir, stem), 'Source')).map(
          (path) => `${stem}/${path}`,
        )
      : []
    return [session.name, ...inside]
  })
  return nested
    .flat()
    .sort(byText)
    .map((path) => ({ project, path }))
}

export const listSessionFiles = async (
  sourceRoot: string,
  prefix: string,
): Promise<readonly SessionFile[]> => {
  const projects = (await readDirents(sourceRoot, 'Source'))
    .filter((entry) => entry.isDirectory() && entry.name.startsWith(prefix))
    .map((entry) => entry.name)
    .sort(byText)

}

export const openAskOrRefine = (handle: EditorHandle): boolean => {
  const active = activeAtCursor(handle.state)
  if (active === undefined || !handle.state.selection.main.empty)
    return openAsk(handle)
  if (active.refine.status === 'working') return false
  handle.dispatch({ effects: openRefineEffect.of(active.id) })
  return true
}

const closeRefineInput = (handle: EditorHandle): boolean => {
  if (refineInputOpenFor(handle.state) === null) return false
  handle.dispatch({ effects: closeRefineEffect.of(null) })
  return true
}

const cancelRefineAtCursor = (handle: EditorHandle): boolean => {
  const found = suggestionAtCursor(handle.state)
  if (found?.status !== 'ready' || found.refine.status === 'idle') return false
  handle.dispatch({ effects: cancelRefineEffect.of(found.id) })
  return true
}

const dismissBubble = (handle: EditorHandle): boolean => {
  if (!bubbleVisible(handle.state)) return false
  handle.dispatch({ effects: dismissBubbleEffect.of(null) })
  return true
}

export const escapeAtCursor = (handle: EditorHandle): boolean =>
  dismissBubble(handle) ||
  closeRefineInput(handle) ||
  cancelRefineAtCursor(handle) ||
  rejectAtCursor(handle)

export const suggestionKeymap = Prec.highest(
  keymap.of([
    { key: 'Mod-k', run: openAskOrRefine, preventDefault: true },
    { key: 'Mod-Enter', run: acceptAtCursor },
    { key: 'Escape', run: escapeAtCursor },
  ]),
)
